import{_ as e,o as a,c as o,ag as s}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Upstream Proxy","description":"Chain NectoProxy with another upstream proxy for corporate environments, Tor, and VPN integration.","frontmatter":{"title":"Upstream Proxy","description":"Chain NectoProxy with another upstream proxy for corporate environments, Tor, and VPN integration."},"headers":[],"relativePath":"features/upstream-proxy.md","filePath":"features/upstream-proxy.md","lastUpdated":1772297611000}'),n={name:"features/upstream-proxy.md"};function r(i,t,p,c,l,h){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="upstream-proxy" tabindex="-1">Upstream Proxy <a class="header-anchor" href="#upstream-proxy" aria-label="Permalink to &quot;Upstream Proxy&quot;">​</a></h1><p>NectoProxy can be configured to forward all traffic through an <strong>upstream proxy</strong> rather than connecting directly to target servers. This is commonly known as <strong>proxy chaining</strong> and is essential in corporate environments, for routing through anonymizing networks, or when you need NectoProxy to work behind an existing proxy infrastructure.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>In a typical proxy configuration, the traffic flow is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client --&gt; NectoProxy --&gt; Target Server</span></span></code></pre></div><p>With an upstream proxy configured, the flow becomes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client --&gt; NectoProxy --&gt; Upstream Proxy --&gt; Target Server</span></span></code></pre></div><p>NectoProxy handles the MITM interception and all its features (rules, breakpoints, inspection) locally, and then forwards the traffic through the upstream proxy to reach the target server.</p><h2 id="supported-protocols" tabindex="-1">Supported Protocols <a class="header-anchor" href="#supported-protocols" aria-label="Permalink to &quot;Supported Protocols&quot;">​</a></h2><p>NectoProxy supports four upstream proxy protocols:</p><h3 id="http-proxy" tabindex="-1">HTTP Proxy <a class="header-anchor" href="#http-proxy" aria-label="Permalink to &quot;HTTP Proxy&quot;">​</a></h3><p>The most common proxy protocol. NectoProxy sends HTTP <code>CONNECT</code> requests to the upstream proxy for HTTPS traffic and direct HTTP requests for plain HTTP traffic.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Protocol:  HTTP</span></span>
<span class="line"><span>Host:      proxy.corp.example.com</span></span>
<span class="line"><span>Port:      8080</span></span></code></pre></div><h3 id="https-proxy" tabindex="-1">HTTPS Proxy <a class="header-anchor" href="#https-proxy" aria-label="Permalink to &quot;HTTPS Proxy&quot;">​</a></h3><p>Identical to HTTP proxy but the connection between NectoProxy and the upstream proxy is encrypted with TLS. This protects the proxy traffic from interception on the network between NectoProxy and the upstream proxy.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Protocol:  HTTPS</span></span>
<span class="line"><span>Host:      secure-proxy.corp.example.com</span></span>
<span class="line"><span>Port:      443</span></span></code></pre></div><h3 id="socks4" tabindex="-1">SOCKS4 <a class="header-anchor" href="#socks4" aria-label="Permalink to &quot;SOCKS4&quot;">​</a></h3><p>The SOCKS4 protocol provides a generic proxy mechanism that works at the TCP level. SOCKS4 supports TCP connections but does not support UDP or authentication.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Protocol:  SOCKS4</span></span>
<span class="line"><span>Host:      socks-proxy.example.com</span></span>
<span class="line"><span>Port:      1080</span></span></code></pre></div><h3 id="socks5" tabindex="-1">SOCKS5 <a class="header-anchor" href="#socks5" aria-label="Permalink to &quot;SOCKS5&quot;">​</a></h3><p>The most versatile SOCKS protocol. SOCKS5 supports TCP and UDP connections, IPv6 addresses, and username/password authentication. This is the protocol used by Tor and many VPN services.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Protocol:  SOCKS5</span></span>
<span class="line"><span>Host:      socks5-proxy.example.com</span></span>
<span class="line"><span>Port:      1080</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Choosing a Protocol</p><ul><li>Use <strong>HTTP/HTTPS</strong> for standard corporate proxy environments</li><li>Use <strong>SOCKS5</strong> for Tor routing, VPN integration, or when you need authentication with a generic proxy</li><li>Use <strong>SOCKS4</strong> only for legacy proxy servers that do not support SOCKS5</li></ul></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>NectoProxy supports <strong>proxy authentication</strong> for upstream proxies that require credentials.</p><h3 id="http-https-proxy-authentication" tabindex="-1">HTTP/HTTPS Proxy Authentication <a class="header-anchor" href="#http-https-proxy-authentication" aria-label="Permalink to &quot;HTTP/HTTPS Proxy Authentication&quot;">​</a></h3><p>For HTTP and HTTPS upstream proxies, NectoProxy sends credentials using the <code>Proxy-Authorization</code> header with Basic authentication:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Proxy-Authorization: Basic dXNlcm5hbWU6cGFzc3dvcmQ=</span></span></code></pre></div><h3 id="socks5-authentication" tabindex="-1">SOCKS5 Authentication <a class="header-anchor" href="#socks5-authentication" aria-label="Permalink to &quot;SOCKS5 Authentication&quot;">​</a></h3><p>For SOCKS5 proxies, NectoProxy supports username/password authentication as defined in RFC 1929.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Set authentication credentials in the upstream proxy settings:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Username</strong></td><td>The proxy account username</td></tr><tr><td><strong>Password</strong></td><td>The proxy account password</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Proxy credentials are stored in NectoProxy&#39;s configuration. Ensure that your NectoProxy instance is secured appropriately, especially in shared environments. Do not share configuration files that contain proxy credentials.</p></div><h2 id="bypass-rules" tabindex="-1">Bypass Rules <a class="header-anchor" href="#bypass-rules" aria-label="Permalink to &quot;Bypass Rules&quot;">​</a></h2><p>Not all traffic needs to go through the upstream proxy. <strong>Bypass rules</strong> let you specify domains or patterns that should be connected to directly, skipping the upstream proxy.</p><h3 id="common-bypass-scenarios" tabindex="-1">Common Bypass Scenarios <a class="header-anchor" href="#common-bypass-scenarios" aria-label="Permalink to &quot;Common Bypass Scenarios&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pattern</th><th>Reason</th></tr></thead><tbody><tr><td><code>localhost</code></td><td>Local development servers</td></tr><tr><td><code>127.0.0.1</code></td><td>Loopback traffic</td></tr><tr><td><code>*.local</code></td><td>Local network domains</td></tr><tr><td><code>10.*</code></td><td>Internal network (RFC 1918)</td></tr><tr><td><code>192.168.*</code></td><td>Internal network (RFC 1918)</td></tr><tr><td><code>172.16.*</code> through <code>172.31.*</code></td><td>Internal network (RFC 1918)</td></tr><tr><td><code>*.corp.example.com</code></td><td>Internal corporate services</td></tr></tbody></table><h3 id="bypass-pattern-format" tabindex="-1">Bypass Pattern Format <a class="header-anchor" href="#bypass-pattern-format" aria-label="Permalink to &quot;Bypass Pattern Format&quot;">​</a></h3><p>Bypass rules support:</p><ul><li><strong>Exact domains</strong>: <code>internal.example.com</code></li><li><strong>Wildcard domains</strong>: <code>*.internal.example.com</code></li><li><strong>IP addresses</strong>: <code>192.168.1.100</code></li><li><strong>IP ranges</strong>: <code>10.*</code>, <code>192.168.*</code></li></ul><details class="details custom-block"><summary>Example: Corporate Environment Configuration</summary><p>In a corporate environment, you might configure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Upstream Proxy:</span></span>
<span class="line"><span>  Protocol:   HTTP</span></span>
<span class="line"><span>  Host:       proxy.corp.example.com</span></span>
<span class="line"><span>  Port:       8080</span></span>
<span class="line"><span>  Username:   john.doe</span></span>
<span class="line"><span>  Password:   ********</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bypass Rules:</span></span>
<span class="line"><span>  - localhost</span></span>
<span class="line"><span>  - 127.0.0.1</span></span>
<span class="line"><span>  - *.corp.example.com</span></span>
<span class="line"><span>  - 10.*</span></span>
<span class="line"><span>  - 192.168.*</span></span>
<span class="line"><span>  - *.local</span></span></code></pre></div><p>This routes all external traffic through the corporate proxy while keeping internal traffic direct.</p></details><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="corporate-proxy-environment" tabindex="-1">Corporate Proxy Environment <a class="header-anchor" href="#corporate-proxy-environment" aria-label="Permalink to &quot;Corporate Proxy Environment&quot;">​</a></h3><p>Most corporate networks require all internet traffic to pass through a corporate proxy server. Without upstream proxy support, NectoProxy would not be able to reach external servers.</p><p><strong>Configuration:</strong></p><ol><li>Set the upstream proxy to your corporate proxy server</li><li>Add bypass rules for internal services</li><li>Set authentication credentials if required</li></ol><p>NectoProxy functions normally within the corporate network, with all its features available. Traffic is inspected locally and then forwarded through the corporate proxy.</p><h3 id="routing-through-tor" tabindex="-1">Routing Through Tor <a class="header-anchor" href="#routing-through-tor" aria-label="Permalink to &quot;Routing Through Tor&quot;">​</a></h3><p>Use NectoProxy with the Tor network for anonymous traffic inspection:</p><p><strong>Configuration:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Protocol:   SOCKS5</span></span>
<span class="line"><span>Host:       127.0.0.1</span></span>
<span class="line"><span>Port:       9050</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>When routing through Tor, be aware of the significant latency increase. Tor routes traffic through multiple relays, which typically adds 500-2000 ms of latency per request. Adjust any timeout settings accordingly.</p></div><h3 id="vpn-integration" tabindex="-1">VPN Integration <a class="header-anchor" href="#vpn-integration" aria-label="Permalink to &quot;VPN Integration&quot;">​</a></h3><p>Some VPN configurations expose a SOCKS proxy interface. NectoProxy can route traffic through the VPN&#39;s proxy to ensure traffic is encrypted and routed through the VPN tunnel.</p><p><strong>Configuration:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Protocol:   SOCKS5</span></span>
<span class="line"><span>Host:       127.0.0.1</span></span>
<span class="line"><span>Port:       1080</span></span></code></pre></div><h3 id="multi-layer-security-testing" tabindex="-1">Multi-Layer Security Testing <a class="header-anchor" href="#multi-layer-security-testing" aria-label="Permalink to &quot;Multi-Layer Security Testing&quot;">​</a></h3><p>For security testing scenarios, you might chain NectoProxy through a different proxy to reach a target network:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client --&gt; NectoProxy (inspect traffic) --&gt; Upstream Proxy (network access) --&gt; Target</span></span></code></pre></div><p>This lets you use NectoProxy&#39;s inspection and modification features while relying on another proxy for network routing and access control.</p><h3 id="geographic-testing" tabindex="-1">Geographic Testing <a class="header-anchor" href="#geographic-testing" aria-label="Permalink to &quot;Geographic Testing&quot;">​</a></h3><p>Route traffic through a proxy in a different geographic location to test geo-specific behavior:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Protocol:   SOCKS5</span></span>
<span class="line"><span>Host:       us-proxy.example.com</span></span>
<span class="line"><span>Port:       1080</span></span></code></pre></div><p>This can be used to test CDN behavior, geo-restricted content, or locale-specific API responses.</p><h2 id="configuration-through-the-ui" tabindex="-1">Configuration Through the UI <a class="header-anchor" href="#configuration-through-the-ui" aria-label="Permalink to &quot;Configuration Through the UI&quot;">​</a></h2><p>The upstream proxy is configured through the <strong>Settings</strong> panel in the NectoProxy Web UI.</p><h3 id="settings-panel" tabindex="-1">Settings Panel <a class="header-anchor" href="#settings-panel" aria-label="Permalink to &quot;Settings Panel&quot;">​</a></h3><ol><li>Open <strong>Settings</strong> from the navigation bar</li><li>Navigate to the <strong>Upstream Proxy</strong> section</li><li>Toggle <strong>Enable Upstream Proxy</strong></li><li>Fill in the proxy details: <ul><li>Protocol (HTTP, HTTPS, SOCKS4, SOCKS5)</li><li>Host</li><li>Port</li><li>Username (optional)</li><li>Password (optional)</li></ul></li><li>Add bypass rules as needed</li><li>Save the configuration</li></ol><h3 id="testing-the-connection" tabindex="-1">Testing the Connection <a class="header-anchor" href="#testing-the-connection" aria-label="Permalink to &quot;Testing the Connection&quot;">​</a></h3><p>After configuring the upstream proxy, send a test request through NectoProxy to verify connectivity. Check the traffic list for successful responses. If requests fail, check:</p><ul><li>The upstream proxy host and port are correct</li><li>Authentication credentials are valid</li><li>The upstream proxy is reachable from NectoProxy&#39;s network</li><li>Bypass rules are not inadvertently excluding the test domain</li></ul><h2 id="interaction-with-other-features" tabindex="-1">Interaction with Other Features <a class="header-anchor" href="#interaction-with-other-features" aria-label="Permalink to &quot;Interaction with Other Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Interaction</th></tr></thead><tbody><tr><td><strong>Traffic Inspection</strong></td><td>Works normally. All inspection features are available regardless of upstream proxy configuration.</td></tr><tr><td><strong>Rules Engine</strong></td><td>Rules are applied before traffic is sent to the upstream proxy.</td></tr><tr><td><strong>Breakpoints</strong></td><td>Breakpoints pause traffic before it reaches the upstream proxy.</td></tr><tr><td><strong>SSL Passthrough</strong></td><td>Passthrough traffic is tunneled directly through the upstream proxy without MITM.</td></tr><tr><td><strong>DNS Mapping</strong></td><td>DNS mappings are applied before the upstream proxy connection. The proxy may perform its own DNS resolution.</td></tr><tr><td><strong>Network Conditioning</strong></td><td>Network conditioning is applied between the client and NectoProxy, not between NectoProxy and the upstream proxy.</td></tr></tbody></table><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Upstream proxy settings are persisted across NectoProxy sessions. Your configuration is saved and automatically applied when you restart the proxy.</p></div>`,76)])])}const g=e(n,[["render",r]]);export{u as __pageData,g as default};
